async function unzip(buffer){const b=new Uint8Array(buffer),v=new DataView(buffer);let end=-1;for(let i=b.length-22;i>=Math.max(0,b.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('ملف Excel غير صالح');const count=v.getUint16(end+10,true);if(count>1000)throw Error('عدد ملفات Excel الداخلية أكبر من الحد');let at=v.getUint32(end+16,true),total=0;const out={};for(let i=0;i<count;i++){if(at+46>b.length||v.getUint32(at,true)!==0x02014b50)throw Error('بنية Excel غير صالحة');const flags=v.getUint16(at+8,true),method=v.getUint16(at+10,true),size=v.getUint32(at+20,true),raw=v.getUint32(at+24,true),nl=v.getUint16(at+28,true),xl=v.getUint16(at+30,true),cl=v.getUint16(at+32,true),pos=v.getUint32(at+42,true),hash=v.getUint32(at+16,true);total+=raw;if(total>20e6||raw>10e6||flags&1)throw Error('الملف مشفر أو يتجاوز حد المعالجة');const name=dec.decode(b.subarray(at+46,at+46+nl));if(pos+30>b.length||v.getUint32(pos,true)!==0x04034b50)throw Error('بنية Excel غير صالحة');const start=pos+30+v.getUint16(pos+26,true)+v.getUint16(pos+28,true);if(start+size>b.length)throw Error('ملف Excel غير مكتمل');let data=b.slice(start,start+size);if(method===8){try{data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer())}catch{throw Error('تعذر فتح Excel في هذا المتصفح؛ احفظ الملف بصيغة CSV')}}else if(method!==0)throw Error('نوع ضغط Excel غير مدعوم');if(data.length!==raw||crc(data)!==hash)throw Error('ملف Excel تالف');out[name]=dec.decode(data);at+=46+nl+xl+cl}return out}
